/* Dependency-free QR encoder: QR version 10, error correction L, byte mode,
 * mask 0. ISO/IEC 18004 layout. Max 271 UTF-8 bytes; longer links use Copy/Share.
 * This implementation is original to this project. */
(() => {
  const size=57,dataWords=274,eccWords=18,blocks=[68,68,69,69];
  function multiply(a,b){let z=0;for(let i=7;i>=0;i--){z=(z<<1)^((z>>>7)*0x11d);z^=((b>>>i)&1)*a;}return z;}
  function remainder(data){let divisor=new Uint8Array(eccWords);divisor[eccWords-1]=1;let root=1;for(let i=0;i<eccWords;i++){for(let j=0;j<eccWords;j++){divisor[j]=multiply(divisor[j],root);if(j+1<eccWords)divisor[j]^=divisor[j+1];}root=multiply(root,2);}const result=new Uint8Array(eccWords);for(const b of data){const factor=b^result[0];result.copyWithin(0,1);result[eccWords-1]=0;for(let i=0;i<eccWords;i++)result[i]^=multiply(divisor[i],factor);}return result;}
  function encode(text){const input=new TextEncoder().encode(text);if(input.length>271)throw new Error('Pairing URL too long for QR. Use Copy or Share.');const bits=[];const put=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>>i)&1);};put(4,4);put(input.length,16);for(const b of input)put(b,8);put(0,Math.min(4,dataWords*8-bits.length));while(bits.length%8)bits.push(0);const data=[];for(let i=0;i<bits.length;i+=8)data.push(bits.slice(i,i+8).reduce((a,b)=>a*2+b,0));for(let pad=0;data.length<dataWords;pad++)data.push(pad%2?0x11:0xec);
    let offset=0;const chunks=blocks.map(n=>{const d=data.slice(offset,offset+n);offset+=n;return{data:d,ecc:remainder(d)};});const words=[];for(let i=0;i<69;i++)for(const b of chunks)if(i<b.data.length)words.push(b.data[i]);for(let i=0;i<eccWords;i++)for(const b of chunks)words.push(b.ecc[i]);
    const matrix=Array.from({length:size},()=>Array(size).fill(false));const locked=Array.from({length:size},()=>Array(size).fill(false));const set=(x,y,v)=>{if(x>=0&&y>=0&&x<size&&y<size){matrix[y][x]=!!v;locked[y][x]=true;}};
    for(let i=0;i<size;i++){set(6,i,i%2===0);set(i,6,i%2===0);}for(const[cx,cy]of[[3,3],[size-4,3],[3,size-4]])for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){const dist=Math.max(Math.abs(dx),Math.abs(dy));set(cx+dx,cy+dy,dist!==2&&dist!==4);}
    const pos=[6,28,50];for(let i=0;i<3;i++)for(let j=0;j<3;j++){if((i===0&&j===0)||(i===0&&j===2)||(i===2&&j===0))continue;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)set(pos[i]+dx,pos[j]+dy,Math.max(Math.abs(dx),Math.abs(dy))!==1);}
    let rem=8;for(let i=0;i<10;i++)rem=(rem<<1)^((rem>>>9)*0x537);const format=((8<<10)|rem)^0x5412;const bit=i=>(format>>>i)&1;for(let i=0;i<=5;i++)set(8,i,bit(i));set(8,7,bit(6));set(8,8,bit(7));set(7,8,bit(8));for(let i=9;i<15;i++)set(14-i,8,bit(i));for(let i=0;i<8;i++)set(size-1-i,8,bit(i));for(let i=8;i<15;i++)set(8,size-15+i,bit(i));set(8,size-8,true);
    let version=10;for(let i=0;i<12;i++)version=(version<<1)^((version>>>11)*0x1f25);version|=10<<12;for(let i=0;i<18;i++){const a=size-11+i%3,b=Math.floor(i/3),v=(version>>>i)&1;set(a,b,v);set(b,a,v);}
    let index=0;for(let right=size-1;right>=1;right-=2){if(right===6)right=5;for(let vert=0;vert<size;vert++){const upward=((right+1)&2)===0;const y=upward?size-1-vert:vert;for(let j=0;j<2;j++){const x=right-j;if(locked[y][x])continue;const v=index<words.length*8?((words[index>>>3]>>>(7-(index&7)))&1):0;matrix[y][x]=!!(v^((x+y)%2===0?1:0));index++;}}}return matrix;
  }
  window.qrcode=()=>{let text='',matrix=null;return{addData(value){text=value;},make(){matrix=encode(text);},createSvgTag(){if(!matrix)matrix=encode(text);const margin=4;const d=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(matrix[y][x])d.push(`M${x+margin},${y+margin}h1v1h-1z`);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size+8} ${size+8}" role="img" aria-label="Scan to pair your phone" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><path d="${d.join('')}" fill="black"/></svg>`;}};};
})();
